CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0, stock integer NOT NULL DEFAULT 0, category text DEFAULT 'Ropa deportiva', sizes text DEFAULT '', colors text DEFAULT '', image_url text DEFAULT '', featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())